/**
 * @fileoverview Message Related Type Definitions
 * @description Defines core data types for the messenger module, including message entities, request parameters, and response types
 * @version 3.0.0
 * @module @shinwa/messenger-shared/types
 */

// ============================================================================
// Basic Type Definitions
// ============================================================================

/**
 * Message Type
 * @description Defines message types supported by the system
 *
 * - `SYSTEM`: System message - Notifications automatically generated by the system
 * - `NOTIFICATION`: Notification message - Notifications generated by business modules
 * - `PRIVATE`: Private message - Private conversations between users
 * - `BROADCAST`: Broadcast message - Announcements sent to all users
 */
export type MessageType = 'SYSTEM' | 'NOTIFICATION' | 'PRIVATE' | 'BROADCAST';

/**
 * Message Status
 * @description Defines message lifecycle statuses
 *
 * - `UNREAD`: Unread - Message delivered but not viewed
 * - `READ`: Read - Message has been viewed by recipient
 * - `ARCHIVED`: Archived - Message has been archived
 * - `DELETED`: Deleted - Message has been soft deleted
 */
export type MessageStatus = 'UNREAD' | 'READ' | 'ARCHIVED' | 'DELETED';

// ============================================================================
// Data Transfer Objects (DTO)
// ============================================================================

/**
 * Message Data Transfer Object
 * @description Complete data structure for message entities, used for frontend-backend data transfer
 *
 * @example
 * ```typescript
 * const message: MessageDTO = {
 *   id: 'msg-001',
 *   title: 'System Notification',
 *   content: 'Your order has been shipped',
 *   type: 'NOTIFICATION',
 *   status: 'UNREAD',
 *   senderId: 'system',
 *   senderName: 'System',
 *   receiverId: 'user-001',
 *   createdAt: '2024-01-01T00:00:00Z',
 *   readAt: null,
 * };
 * ```
 */
export interface MessageDTO {
  /**
   * Message unique identifier
   * @description System-generated UUID format identifier
   */
  id: string;

  /**
   * Message title
   * @description Short summary of the message, used for list display
   */
  title: string;

  /**
   * Message content
   * @description Detailed content of the message, supports rich text format
   */
  content: string;

  /**
   * Message type
   * @see MessageType
   */
  type: MessageType;

  /**
   * Message status
   * @see MessageStatus
   */
  status: MessageStatus;

  /**
   * Sender ID
   * @description Identifier of the user or system that sent the message
   */
  senderId: string;

  /**
   * Sender name
   * @description Display name of the sender
   */
  senderName: string;

  /**
   * Sender avatar URL
   * @description Optional sender avatar image URL
   */
  senderAvatar?: string;

  /**
   * Receiver ID
   * @description User identifier of the message recipient
   */
  receiverId: string;

  /**
   * Receiver name
   * @description Display name of the recipient
   */
  receiverName?: string;

  /**
   * Created time
   * @description ISO 8601 format timestamp
   */
  createdAt: string;

  /**
   * Read time
   * @description Time when the message was read, null if unread
   */
  readAt: string | null;

  /**
   * Archived time
   * @description Time when the message was archived, null if not archived
   */
  archivedAt?: string | null;

  /**
   * Deleted time
   * @description Time when the message was soft deleted, null if not deleted
   */
  deletedAt?: string | null;

  /**
   * Message priority
   * @description Urgency level of the message, range 1-5, default is 3
   */
  priority?: number;

  /**
   * Related business type
   * @description Business module identifier associated with the message
   */
  businessType?: string;

  /**
   * Related business ID
   * @description Business entity ID associated with the message
   */
  businessId?: string;

  /**
   * Extended data
   * @description Additional metadata for the message, JSON format
   */
  metadata?: Record<string, unknown>;
}

// ============================================================================
// Request Parameter Types
// ============================================================================

/**
 * Create Message Parameters
 * @description Request parameters for creating a new message
 *
 * @example
 * ```typescript
 * const params: CreateMessageParams = {
 *   title: 'Private Message',
 *   content: 'Hello, are you available?',
 *   type: 'PRIVATE',
 *   receiverId: 'user-002',
 * };
 * ```
 */
export interface CreateMessageParams {
  /**
   * Message title
   * @description Required, maximum length 200 characters
   */
  title: string;

  /**
   * Message content
   * @description Required, maximum length 10000 characters
   */
  content: string;

  /**
   * Message type
   * @description Required, specifies the message type
   */
  type: MessageType;

  /**
   * Receiver ID
   * @description Required for private messages, optional for broadcasts
   */
  receiverId?: string;

  /**
   * Message priority
   * @description Optional, defaults to 3
   */
  priority?: number;

  /**
   * Related business type
   */
  businessType?: string;

  /**
   * Related business ID
   */
  businessId?: string;

  /**
   * Extended data
   */
  metadata?: Record<string, unknown>;
}

/**
 * Update Message Parameters
 * @description Request parameters for updating a message
 */
export interface UpdateMessageParams {
  /**
   * Message ID
   * @description Required, identifier of the message to update
   */
  id: string;

  /**
   * Message status
   * @description Optional, updates the message status
   */
  status?: MessageStatus;

  /**
   * Message title
   * @description Optional, only draft messages can be updated
   */
  title?: string;

  /**
   * Message content
   * @description Optional, only draft messages can be updated
   */
  content?: string;
}

/**
 * Message Query Parameters
 * @description Filter and pagination parameters for querying message list
 *
 * @example
 * ```typescript
 * const query: MessageQueryParams = {
 *   type: 'NOTIFICATION',
 *   status: 'UNREAD',
 *   page: 1,
 *   pageSize: 20,
 *   sortBy: 'createdAt',
 *   sortOrder: 'desc',
 * };
 * ```
 */
export interface MessageQueryParams {
  /**
   * Message type filter
   * @description Optional, filters messages of specified type
   */
  type?: MessageType;

  /**
   * Message status filter
   * @description Optional, filters messages of specified status
   */
  status?: MessageStatus;

  /**
   * Sender ID filter
   */
  senderId?: string;

  /**
   * Keyword search
   * @description Searches keywords in title and content
   */
  keyword?: string;

  /**
   * Start time
   * @description ISO 8601 format, filters messages after this time
   */
  startTime?: string;

  /**
   * End time
   * @description ISO 8601 format, filters messages before this time
   */
  endTime?: string;

  /**
   * Page number
   * @description Starts from 1, defaults to 1
   */
  page?: number;

  /**
   * Page size
   * @description Defaults to 20, maximum 100
   */
  pageSize?: number;

  /**
   * Sort field
   * @description Defaults to 'createdAt'
   */
  sortBy?: 'createdAt' | 'readAt' | 'priority';

  /**
   * Sort order
   * @description Defaults to 'desc' (descending)
   */
  sortOrder?: 'asc' | 'desc';
}

// ============================================================================
// Response Types
// ============================================================================

/**
 * Message List Response
 * @description Response data structure for querying message list
 */
export interface MessageListResponse {
  /**
   * Message list
   */
  items: MessageDTO[];

  /**
   * Total count
   */
  total: number;

  /**
   * Current page number
   */
  page: number;

  /**
   * Page size
   */
  pageSize: number;

  /**
   * Total pages
   */
  totalPages: number;

  /**
   * Has next page
   */
  hasNext: boolean;

  /**
   * Has previous page
   */
  hasPrev: boolean;
}

/**
 * Message Detail Response
 * @description Response data structure for getting single message detail
 */
export interface MessageDetailResponse {
  /**
   * Message data
   */
  data: MessageDTO;

  /**
   * Related messages (e.g., context messages in a conversation)
   */
  relatedMessages?: MessageDTO[];
}
